import { pipeline, Readable, Writable, Transform } from "node:stream";
function main(): void {
  const up = new Transform({ transform(c, _e, cb) { cb(null, c.toString().toUpperCase()); } });
  const out: string[] = [];
  pipeline(Readable.from(["a", "b", "c"]), up, new Writable({ write(c, _e, cb) { out.push(c.toString()); cb(); } }), (e) => console.log("pipeline", e, out));
}
